  Q.r1 = { t: 'Productos caros', cc: 'SELECT, WHERE, ORDER BY', k: 'Lista los productos que cuestan más de 4.00. Devuelve <code>name</code>, <code>category</code> y <code>price</code>, del más caro al más barato (empates por nombre).', h: 'SELECT de las tres columnas FROM products, filtra con WHERE price > 4 y después ORDER BY price DESC, name.' };
